const description: { en: string; ja: string } = {"en":"Three broad waves chase each other round a circle. Use the three-comma tomoe's rim and head circles. Enlarge each inner tail circle a little about its original point of contact to leave a clear paper channel. Three equal-width paper lines follow concentric arcs from the tail to the head. Two tangent arcs ease each shoulder into a smaller head circle; three identical foam curls sit on that circle. Turn the whole wave by one third and two thirds of a circle.","ja":"三つの幅広い波が円の中を追いかけます。三つ巴の外円と頭の円を使います。尾の内側の円を元の接点を保ったまま少し広げ、波と波の間を白くあけます。同じ幅の三本の白い線は、同心の円弧で尾から頭まで伸びます。肩は接する二本の円弧で小さな頭の円につながり、その円に同じ波頭の巻きを三つ置きます。波全体を円の3分の1と3分の2ずつ回します。"};

export default construction;
export { construction, description };
